// Validate Settings and turn the watchlist into one item per company.
// Each watchlist line: companyNumber | label (optional) | warnDays (optional).
// Plain comma-separated numbers also work.
const cfg = $('Settings').first().json;
const raw = String(cfg.watchlist || cfg.companyNumbers || '');

function normNumber(n) {
  const s = String(n ?? '').trim().toUpperCase().replace(/\s+/g, '');
  if (!/^[A-Z0-9]{1,8}$/.test(s)) {
    throw new Error('Invalid company number: "' + n + '". Use numbers such as 00445790, SC123456 or NI036672.');
  }
  if (/^\d+$/.test(s)) return s.padStart(8, '0');
  return s.length < 8 ? s.slice(0, 2) + s.slice(2).padStart(6, '0') : s;
}

const defaultWarn = Number(cfg.defaultWarnDays ?? cfg.dueWithinDays ?? 30);
if (!(defaultWarn >= 1 && defaultWarn <= 365)) {
  throw new Error('Settings.defaultWarnDays must be between 1 and 365.');
}
const ladder = String(cfg.reminderDays ?? '').split(/[ ,;]+/).filter(Boolean).map(Number);
if (ladder.some(d => !(d >= 0 && d <= 365))) {
  throw new Error('Settings.reminderDays must be a list of whole days between 0 and 365, e.g. "30, 14, 7, 1".');
}
const repeat = Number(cfg.overdueRepeatDays ?? 7);
if (!(repeat >= 1 && repeat <= 90)) throw new Error('Settings.overdueRepeatDays must be between 1 and 90.');
const delay = Number(cfg.delaySeconds);
if (!(delay >= 0 && delay <= 30)) throw new Error('Settings.delaySeconds must be between 0 and 30.');
const max = Math.min(Math.max(Number(cfg.maxCompanies) || 100, 1), 250);

const entries = [];
for (const line of raw.split(/[\n;]+/).map(s => s.trim()).filter(Boolean)) {
  if (line.startsWith('#')) continue; // allow comment lines
  if (line.includes('|')) {
    const [num, label, warn] = line.split('|').map(s => s.trim());
    entries.push({ num, label, warn });
  } else {
    for (const num of line.split(',').map(s => s.trim()).filter(Boolean)) entries.push({ num, label: '', warn: '' });
  }
}
if (!entries.length) {
  throw new Error('Add at least one UK company number to Settings.watchlist, e.g. "00445790 | Client name | 45".');
}

const seen = new Set();
const out = [];
for (const e of entries) {
  const companyNumber = normNumber(e.num);
  if (seen.has(companyNumber)) continue;
  seen.add(companyNumber);
  let warnDays = defaultWarn;
  if (e.warn) {
    warnDays = Number(e.warn);
    if (!(warnDays >= 1 && warnDays <= 365)) {
      throw new Error('Warning window for ' + companyNumber + ' must be 1-365 days, got "' + e.warn + '".');
    }
  }
  out.push({ companyNumber, label: e.label || '', warnDays });
}
if (out.length > max) {
  throw new Error('Watchlist has ' + out.length + ' companies; maxCompanies is ' + max + '. Raise maxCompanies (up to 250) or split the list.');
}
return out.map(x => ({ json: x }));

// Normalise the HTTP response, keep the watchlist label and window, and decide
// whether a filing has been made since the last run (a due date moved forward).
const entry = $('Loop over companies').item.json;
const number = entry.companyNumber;
const j = $json;
let statusCode = j.statusCode;
let body = (j.body !== undefined) ? j.body : j;
let errorMessage = '';
if (j.error) {
  statusCode = Number(j.error.httpCode || j.error.status || j.error.statusCode || statusCode || 0);
  errorMessage = j.error.message || String(j.error);
  body = null;
}
const base = { companyNumber: number, label: entry.label || '', warnDays: entry.warnDays, needsFilingHistory: false, filingEvidence: null };
const fail = (code, msg) => [{ json: { ...base, ok: false, statusCode: code, profile: null, errorMessage: msg } }];

if (statusCode === 401 || /(?:^|\D)401(?:\D|$)/.test(errorMessage)) {
  return fail(401, 'Companies House API 401: the API key was rejected. On Get company profile, add an HTTP Basic Auth credential with your free REST API key as the username and a blank password.');
}
if (statusCode === 404) return fail(404, 'Company not found on the Companies House register. Check the number.');
if (statusCode === 429) return fail(429, 'Rate limited by Companies House (600 requests per 5 minutes). Raise delaySeconds.');
if (statusCode && statusCode !== 200) return fail(statusCode, errorMessage || ('Companies House API HTTP ' + statusCode));
const profile = (body && body.company_number) ? body : null;
if (!profile) return fail(statusCode || 0, errorMessage || 'Unexpected response from the Companies House API.');

// Compare with the last saved snapshot (read only here; the summary node writes it).
const prev = (($getWorkflowStaticData('global').companies) || {})[number];
const acc = profile.accounts || {};
const accDue = (acc.next_accounts && acc.next_accounts.due_on) || acc.next_due || null;
const csDue = (profile.confirmation_statement && profile.confirmation_statement.next_due) || null;
const movedOn = (oldDue, newDue) => !!(oldDue && newDue && newDue > oldDue);
const needsFilingHistory = !!prev && (movedOn(prev.accountsNextDue, accDue) || movedOn(prev.confirmationNextDue, csDue));

return [{ json: { ...base, ok: true, statusCode: statusCode || 200, profile, errorMessage: '', needsFilingHistory } }];

// Add the most recent accounts and confirmation-statement filings as evidence
// that a filing was made. A failed lookup never stops the run.
const base = $('Check response and detect filing').item.json;
const j = $json;
const body = (j.body !== undefined) ? j.body : j;
const items = (body && Array.isArray(body.items)) ? body.items : [];
const pick = cat => {
  const f = items.filter(i => i.category === cat).sort((a, b) => String(b.date).localeCompare(String(a.date)))[0];
  if (!f) return null;
  return {
    filedOn: f.date || null,
    madeUpTo: (f.description_values && f.description_values.made_up_date) || f.action_date || null,
    type: f.type || null,
    description: f.description || null,
  };
};
const ok = items.length > 0;
const filingEvidence = {
  ok,
  accounts: ok ? pick('accounts') : null,
  confirmation: ok ? pick('confirmation-statement') : null,
  link: 'https://find-and-update.company-information.service.gov.uk/company/' + base.companyNumber + '/filing-history',
  error: ok ? '' : ('Filing history lookup failed' + (j.statusCode ? ' (HTTP ' + j.statusCode + ')' : '') + '; the due-date change is still reported.'),
};
return [{ json: { ...base, filingEvidence } }];

// Reminder ladder with a de-duplication ledger.
// Official company-profile fields: accounts.next_accounts.due_on / overdue
// (accounts.next_due / overdue as fallback), confirmation_statement.next_due /
// overdue / last_made_up_to, company_number, company_name, company_status,
// company_status_detail.
// Each filing gets one reminder per stage of the ladder (e.g. 30, 14, 7, 1 days),
// one overdue alert every overdueRepeatDays, and a "filed" notice when its due
// date moves on. State lives in workflow static data, so repeats are not sent.
const cfg = $('Settings').first().json;
const results = $input.all().map(i => i.json);
const store = $getWorkflowStaticData('global');

if (results.some(r => r.statusCode === 401)) {
  throw new Error('Companies House API 401: the API key was rejected. On Get company profile, add an HTTP Basic Auth credential with your free REST API key as the username and a blank password.');
}
const okRows = results.filter(r => r.ok);
if (!okRows.length) {
  throw new Error('Companies House API failed for every company: ' + results.map(f => f.companyNumber + ' (' + f.errorMessage + ')').join('; '));
}

const DAY = 86400000;
const today = String(cfg.todayOverride || '').trim() || new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/London' });
const daysBetween = (a, b) => Math.round((Date.parse(b) - Date.parse(a)) / DAY);
const weekday = new Date(today + 'T12:00:00Z').toLocaleDateString('en-GB', { weekday: 'long', timeZone: 'UTC' });
const defaultWarn = Number(cfg.defaultWarnDays ?? cfg.dueWithinDays ?? 30);
const ladderCfg = String(cfg.reminderDays ?? '30, 14, 7, 1').split(/[ ,;]+/).filter(Boolean).map(Number);
const overdueRepeatDays = Number(cfg.overdueRepeatDays ?? 7);
const notifyOnFirstRun = cfg.notifyOnFirstRun !== false;
const isDigestDay = cfg.sendWeeklyDigest === true && weekday === String(cfg.digestWeekday || 'Monday');
const ACTIVE = new Set(['active', 'open', 'registered']);
const FILINGS = { accounts: 'Accounts', confirmation: 'Confirmation statement' };
const SEV = { high: 0, medium: 1, info: 2 };

// The stages that apply to one company: its own warning window plus every
// ladder step inside it, largest first.
const stagesFor = warn => [...new Set([warn, ...ladderCfg.filter(d => d < warn)])].sort((a, b) => b - a);

function normalise(r) {
  const p = r.profile;
  const acc = p.accounts || {};
  const nextAcc = acc.next_accounts || {};
  const cs = p.confirmation_statement || {};
  const accDue = nextAcc.due_on || acc.next_due || null;
  const csDue = cs.next_due || null;
  const status = p.company_status || null;
  const statusDetail = p.company_status_detail || null;
  const number = p.company_number || r.companyNumber;
  return {
    companyNumber: number,
    companyName: p.company_name || '',
    label: r.label || '',
    warnDays: Number(r.warnDays) || defaultWarn,
    status,
    statusDetail,
    notActive: !!(status && !ACTIVE.has(status)),
    strikeOff: statusDetail === 'active-proposal-to-strike-off',
    accountsNextDue: accDue,
    accountsOverdue: !!(nextAcc.overdue || acc.overdue) || !!(accDue && accDue < today),
    accountsLastMadeUpTo: (acc.last_accounts && (acc.last_accounts.period_end_on || acc.last_accounts.made_up_to)) || null,
    confirmationNextDue: csDue,
    confirmationOverdue: !!cs.overdue || !!(csDue && csDue < today),
    confirmationLastMadeUpTo: cs.last_made_up_to || null,
    filingEvidence: r.filingEvidence || null,
    sourceUrl: 'https://find-and-update.company-information.service.gov.uk/company/' + number,
  };
}

const prevCompanies = store.companies || null;
const firstRun = !prevCompanies;
const ledger = store.ledger || {};
const failNoticed = store.failNoticed || {};
const newLedger = {};
const events = [];
const companies = okRows.map(normalise);

for (const c of companies) {
  const prev = prevCompanies ? prevCompanies[c.companyNumber] : null;
  const who = { companyNumber: c.companyNumber, companyName: c.companyName, label: c.label, sourceUrl: c.sourceUrl };

  // Status changes, and inactive companies the first time they are seen.
  const statusChanged = prev && (prev.status !== c.status || prev.statusDetail !== c.statusDetail);
  if (statusChanged || (!prev && (c.notActive || c.strikeOff))) {
    const bad = c.notActive || c.strikeOff;
    events.push({ ...who, type: 'status', severity: bad ? 'high' : 'info', filing: '', dueDate: null, daysUntil: null, stage: null,
      detail: (prev ? 'Status ' + (prev.status || '?') + (prev.statusDetail ? ' (' + prev.statusDetail + ')' : '') + ' → ' : 'Status ') +
        (c.status || '?') + (c.statusDetail ? ' (' + c.statusDetail + ')' : '') });
  }

  for (const f of Object.keys(FILINGS)) {
    const due = c[f + 'NextDue'];
    const overdue = c[f + 'Overdue'];
    const prevDue = prev ? prev[f + 'NextDue'] : null;

    // Filed since last run: the due date moved forward.
    if (prevDue && due && due > prevDue) {
      const ev = c.filingEvidence && c.filingEvidence[f];
      events.push({ ...who, type: 'filed', severity: 'info', filing: FILINGS[f], dueDate: due, daysUntil: daysBetween(today, due), stage: null,
        detail: FILINGS[f] + ' filed' + (ev && ev.filedOn ? ' on ' + ev.filedOn : '') + (ev && ev.madeUpTo ? ', made up to ' + ev.madeUpTo : '') +
          '. Next due ' + due + (c.filingEvidence && c.filingEvidence.ok ? '' : ' (filing history not confirmed)'),
        sourceUrl: (c.filingEvidence && c.filingEvidence.link) || c.sourceUrl });
    }
    // Dissolved or closed companies get status alerts only, not filing reminders.
    if (!due || c.notActive) continue;
    const key = c.companyNumber + '|' + f + '|' + due;
    const L = { ...(ledger[key] || {}) };
    const daysUntil = daysBetween(today, due);

    if (overdue) {
      if (!L.overdueSentOn || daysBetween(L.overdueSentOn, today) >= overdueRepeatDays) {
        events.push({ ...who, type: 'overdue', severity: 'high', filing: FILINGS[f], dueDate: due, daysUntil, stage: 'overdue',
          detail: FILINGS[f] + ' overdue by ' + Math.abs(daysUntil) + ' day' + (Math.abs(daysUntil) === 1 ? '' : 's') + ' (due ' + due + ')' + (L.overdueSentOn ? ', repeat reminder' : '') });
        L.overdueSentOn = today;
      }
    } else if (daysUntil <= c.warnDays) {
      const stages = stagesFor(c.warnDays);
      const stage = Math.min(...stages.filter(s => daysUntil <= s));
      if (L.stage === undefined || stage < L.stage) {
        events.push({ ...who, type: 'reminder', severity: daysUntil <= 7 ? 'high' : 'medium', filing: FILINGS[f], dueDate: due, daysUntil, stage,
          detail: FILINGS[f] + ' due ' + due + ' (' + (daysUntil === 0 ? 'today' : 'in ' + daysUntil + ' day' + (daysUntil === 1 ? '' : 's')) + ')' });
        L.stage = stage;
        L.sentOn = today;
      }
    }
    if (Object.keys(L).length) newLedger[key] = L;
  }
}

// Failed lookups: report each company once until it recovers.
const failed = results.filter(r => !r.ok).map(r => ({ companyNumber: r.companyNumber, label: r.label || '', statusCode: r.statusCode, error: r.errorMessage }));
const newFailNoticed = {};
for (const f of failed) {
  if (!failNoticed[f.companyNumber]) {
    events.push({ companyNumber: f.companyNumber, companyName: '', label: f.label, type: 'error', severity: 'medium', filing: '', dueDate: null, daysUntil: null, stage: null,
      detail: 'Could not check: ' + f.error, sourceUrl: 'https://find-and-update.company-information.service.gov.uk/company/' + f.companyNumber });
  }
  newFailNoticed[f.companyNumber] = failNoticed[f.companyNumber] || today;
  // Keep the old ledger entries for a company we could not read this time.
  for (const k of Object.keys(ledger)) if (k.startsWith(f.companyNumber + '|')) newLedger[k] = ledger[k];
}

// Save state. Companies removed from the watchlist drop out; failed ones keep their last snapshot.
const SNAP = ['companyName', 'status', 'statusDetail', 'accountsNextDue', 'confirmationNextDue'];
const snap = {};
for (const f of failed) if (prevCompanies && prevCompanies[f.companyNumber]) snap[f.companyNumber] = prevCompanies[f.companyNumber];
for (const c of companies) snap[c.companyNumber] = Object.fromEntries(SNAP.map(k => [k, c[k]]));
store.companies = snap;
store.ledger = newLedger;
store.failNoticed = newFailNoticed;
store.lastRun = new Date().toISOString();

let mode = 'none';
if (firstRun) mode = notifyOnFirstRun ? 'baseline' : 'none';
else if (events.length) mode = 'alert';
else if (isDigestDay) mode = 'digest';

// Next deadline across the whole watchlist.
const upcoming = companies.flatMap(c => Object.keys(FILINGS).filter(f => c[f + 'NextDue'] && !c[f + 'Overdue'])
  .map(f => ({ c, f, due: c[f + 'NextDue'] }))).sort((a, b) => a.due.localeCompare(b.due));
const next = upcoming[0];
const nextLine = next ? `Next deadline: ${FILINGS[next.f]} for ${next.c.label || next.c.companyName} (${next.c.companyNumber}) on ${next.due}, in ${daysBetween(today, next.due)} days.` : '';

events.sort((a, b) => (SEV[a.severity] - SEV[b.severity]) || ((a.daysUntil ?? 9999) - (b.daysUntil ?? 9999)));
const counts = t => events.filter(e => e.type === t).length;
const n = companies.length + failed.length;
const plural = (k, w, pl) => k + ' ' + (k === 1 ? w : (pl || w + 's'));
const subject = mode === 'baseline'
  ? `Companies House watch started: ${plural(n, 'company', 'companies')}` + (events.length ? `, ${events.length} need attention` : '')
  : mode === 'digest'
    ? `Companies House weekly digest: ${plural(n, 'company', 'companies')}`
    : 'Companies House: ' + [counts('overdue') && plural(counts('overdue'), 'overdue filing'), counts('reminder') && plural(counts('reminder'), 'reminder'),
        counts('filed') && plural(counts('filed'), 'filing') + ' made', counts('status') && plural(counts('status'), 'status change'),
        counts('error') && plural(counts('error'), 'lookup problem')].filter(Boolean).join(', ');

const SECTIONS = [
  ['overdue', 'Overdue'],
  ['reminder', 'Due soon'],
  ['status', 'Status changes'],
  ['filed', 'Filed since the last check'],
  ['error', 'Could not check'],
];
const name = e => (e.label ? e.label + ' — ' : '') + (e.companyName ? e.companyName + ' (' + e.companyNumber + ')' : e.companyNumber);
const credit = 'Source: Companies House Public Data API. Contains public sector information licensed under the Open Government Licence v3.0. Not affiliated with or endorsed by Companies House. Company-level data only (no officer or PSC names).';
const esc = s => String(s ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));

const digestRows = companies.slice().sort((a, b) => String(a.accountsNextDue || '9').localeCompare(String(b.accountsNextDue || '9')));
const textParts = [subject, ''];
const htmlParts = [`<h2>${esc(subject)}</h2>`];
for (const [type, title] of SECTIONS) {
  const list = events.filter(e => e.type === type);
  if (!list.length) continue;
  textParts.push(title + ':', ...list.map(e => `- [${e.severity.toUpperCase()}] ${name(e)}: ${e.detail} ${e.sourceUrl}`), '');
  htmlParts.push(`<h3>${esc(title)}</h3><ul>` + list.map(e => `<li><b>${esc(name(e))}</b>: ${esc(e.detail)} — <a href="${esc(e.sourceUrl)}">record</a></li>`).join('') + '</ul>');
}
if (mode === 'digest' || mode === 'baseline') {
  textParts.push('All watched companies:', ...digestRows.map(c => `- ${c.label ? c.label + ' — ' : ''}${c.companyName} (${c.companyNumber}): ${c.status}; accounts due ${c.accountsNextDue || '—'}${c.accountsOverdue && !c.notActive ? ' OVERDUE' : ''}; confirmation statement due ${c.confirmationNextDue || '—'}${c.confirmationOverdue && !c.notActive ? ' OVERDUE' : ''}`), '');
  htmlParts.push('<h3>All watched companies</h3><table border="1" cellpadding="6" style="border-collapse:collapse"><tr><th>Company</th><th>Status</th><th>Accounts due</th><th>Confirmation statement due</th></tr>' +
    digestRows.map(c => `<tr><td><a href="${esc(c.sourceUrl)}">${esc(c.companyName)}</a><br><small>${esc(c.companyNumber)}${c.label ? ' · ' + esc(c.label) : ''}</small></td><td>${esc(c.status || '—')}</td><td>${c.accountsOverdue && !c.notActive ? '<b>OVERDUE</b> ' : ''}${esc(c.accountsNextDue || '—')}</td><td>${c.confirmationOverdue && !c.notActive ? '<b>OVERDUE</b> ' : ''}${esc(c.confirmationNextDue || '—')}</td></tr>`).join('') + '</table>');
}
if (!events.length && mode !== 'digest' && mode !== 'baseline') textParts.push('Nothing new to report.', '');
if (nextLine) { textParts.push(nextLine); htmlParts.push(`<p>${esc(nextLine)}</p>`); }
textParts.push('', credit);
htmlParts.push(`<p><small>${esc(credit)}</small></p>`);

// Google Sheets: an audit log with one row per event (or per company for a digest).
const rows = (events.length ? events : (mode === 'digest' || mode === 'baseline' ? digestRows.map(c => ({
  companyNumber: c.companyNumber, companyName: c.companyName, label: c.label, type: mode, severity: 'info', filing: '',
  dueDate: [c.accountsNextDue, c.confirmationNextDue].filter(Boolean).sort()[0] || null, daysUntil: null, stage: null,
  detail: `accounts ${c.accountsNextDue || '—'}, confirmation statement ${c.confirmationNextDue || '—'}`, sourceUrl: c.sourceUrl })) : []))
  .map(e => ({ runDate: today, event: e.type, severity: e.severity, companyNumber: e.companyNumber, companyName: e.companyName, label: e.label,
    filing: e.filing, dueDate: e.dueDate, daysUntil: e.daysUntil, reminderStage: e.stage, detail: e.detail, link: e.sourceUrl }));

return [{ json: { mode, firstRun, today, tracked: n, eventCount: events.length, events, failed, companies, rows, subject, summary: textParts.join('\n'), html: htmlParts.join('') } }];

const e = $json.execution || {}; const w = $json.workflow || {};
return [{ json: { subject: `n8n workflow failed: ${w.name || 'UK Companies House filing reminders'}`,
  summary: `Workflow "${w.name}" failed at node "${e.lastNodeExecuted || '?' }": ${(e.error && e.error.message) || 'unknown error'}\n${e.url || ''}` } }];
